#include <chrono>
#include <print>
#include <vector>
#include <utility>

long diff_us(std::chrono::steady_clock::time_point a,
             std::chrono::steady_clock::time_point b) {
    return std::chrono::duration_cast<std::chrono::microseconds>(b - a).count();
}

int main() {
    std::vector<int> big(1000, 1);
    auto t1 = std::chrono::steady_clock::now();
    std::vector<int> copy = big;
    auto t2 = std::chrono::steady_clock::now();
    std::vector<int> moved = std::move(big);
    auto t3 = std::chrono::steady_clock::now();
    std::println("复制 {} 个元素耗时 {} 微秒", copy.size(), diff_us(t1, t2));
    std::println("移动 {} 个元素耗时 {} 微秒", moved.size(), diff_us(t2, t3));   // 一千个元素这一跑，移动那一行还是 0
    return 0;
}

